def transform(grid):
    H, W = grid.shape
    flipped = grid[:, ::-1]
    result = np.zeros((3 * H, 3 * W), dtype=int)
    for bi in range(3):
        for bj in range(3):
            if bi % 2 == 0:
                result[bi * H:(bi + 1) * H, bj * W:(bj + 1) * W] = grid
            else:
                result[bi * H:(bi + 1) * H, bj * W:(bj + 1) * W] = flipped
    return result
